def check_girth(n, generators):
    adj = {i: set() for i in range(n)}
    for i in range(n):
        for g in generators:
            adj[i].add((i + g) % n)
            adj[i].add((i - g) % n)

    # BFS to find shortest cycle
    girth = n + 1
    for i in range(n):
        dist = {i: 0}
        q = [(i, -1)]
        while q:
            u, p = q.pop(0)
            for v in adj[u]:
                if v == p: continue
                if v in dist:
                    girth = min(girth, dist[u] + dist[v] + 1)
                else:
                    dist[v] = dist[u] + 1
                    q.append((v, u))
    return girth

for i in range(1, 13):
    for j in range(i+1, 13):
        g = check_girth(25, [i, j])
        if g >= 7:
            print(f"Found: {i}, {j} with girth {g}")
print("Done")
